/// <summary>
/// N.Freidenberger 14.08.24
/// </summary>
/// <param name = "_value">_value</param>
/// <param name = "_useCachedValue">_useCachedValue</param>
/// <returns>boolean</returns>
public boolean isStringValueMappedToAlternativeField(str _value, boolean _useCachedValue)
{
    boolean        ret = next  isStringValueMappedToAlternativeField(_value,_useCachedValue);

    QueryBuildDataSource rootQBDS = null;
    QueryRun       queryRun; 

    if (this.baseQuery != null && pkFieldBinding.tableId() == tableNum(CustTable) && this.baseQuery.allowCrossCompany() == true)
    {
        container    conCompany = baseQuery.getCompanyRange();
        str          companyFilter = '';
        int          i;

        for (i = 1;i <= conLen(baseQuery.getCompanyRange()); i++)
        {
            str companyName;
            boolean companyIs;
            [companyName,companyIs] = conPeek(baseQuery.getCompanyRange(),i);
            if(companyIs)
            {
                companyFilter = companyName;
            }

        }
        if (companyFilter != '')
        {
            Query pkReferenceQuery = null;
            pkReferenceQuery = new Query();
            pkReferenceQuery.allowCrossCompany(true);
            pkReferenceQuery.addCompanyRange(companyFilter);
            pkReferenceQuery.firstOnly1(true);

            rootQBDS = pkReferenceQuery.addDataSource(tableNum(CustTable));

            // Add the order by, so we can check for an exact match. This is important in cases where the user's entered value
            // matches both an exact match and is a substring of another match. For example, if the user enters "1234" and the DB
            // has values "1234" and "12345", we would like to immediately take "1234" even though there is an ambiguous match.

            str filterValue = '';

            filterValue = SysQueryRangeUtil::literalFilterValue(_value) + "*";


            rootQBDS.addRange(pkFieldBinding.fieldId(), pkFieldBinding.fieldArrayIndex()).value(filterValue);
            queryRun = new QueryRun(pkReferenceQuery);
            while (queryRun.next())
            {
                ret = false;
            }
        }
    }
    return ret;
}
